//export const App = () => <RouterProvider router={router} />


const router = createHashRouter([
    {
      path: "/",
      element: <AppLayout />,
      //loader: AppLayout,
      children: [
        {
          path: "/",
          element: <Announcements />,
          //loader: Announcements,
        },
        {
          path: "announcements",
          element: <Announcements />,
          //loader: Announcements,
        },
        {
          path: "announcements/:announcementKey",
          element: <Announcement />,
          //loader: Announcements,
        },
        {
            path: "alerts",
            element: <Alerts />,
            //loader: Announcements,
          },
          {
            path: "alert",
            element: <Alert />,
            //loader: Announcements,
          },
          {
            path: "alert/:alertkey",
            element: <Alert />,
            //loader: Announcements,
          },
          {
            path: "stocks",
            element: <Stocks />,
          },
          {
            path: "stocks/:stockCode",
            element: <Stock />,
          },
          {
            path: "notifications",
            element: <Notifications />,
          },
      ],
    },
  ]);
  
export const App = () => <RouterProvider router={router} />

export default App;
