export function isNullEmptyOrWhitespace(str:string) {
    return (str === null || str === undefined || typeof str !== 'string' || str.trim() === '');
}

export function validatePhoneNum(num:string){
    const regex = /^\+91[6-9]\d{9}$/;
    return regex.test(num);
}

export function validateEmail(email:string){
    const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return re.test(email);
}

export function getColor(code:string){
    var firstLetter = code.substring(1,2);
    if(firstLetter >= 'A' && firstLetter <= 'G'){
        return 'deeppink'
    }else if(firstLetter >= 'H' && firstLetter <= 'N'){
        return 'darkgreen';
    }else if(firstLetter >= 'O' && firstLetter <= 'U'){
      return 'orangered';
    }else{
        return '#673ab7';
    }
}
