import * as React from 'react';
import Table from '@mui/material/Table';
import TableBody from '@mui/material/TableBody';
import TableCell from '@mui/material/TableCell';
import TableHead from '@mui/material/TableHead';
import TablePagination from '@mui/material/TablePagination';
import TableRow from '@mui/material/TableRow';
import { useEffect } from 'react';
import { visuallyHidden } from '@mui/utils';
import { IStock } from '../../models/stock/stock';
import { getColor } from '../../utility/utility';
import { TableSortLabel, Box } from '@mui/material';
import { StockAvatar } from '../common/utilitycomp';

const StocksTable = (props: IStockTableTableTableProps)  => {
  
    const {
        rows
      } = props;

  const [rowsData, setRowsData] = React.useState<IStock[]>(rows);
  const [order, setOrder] = React.useState<Order>('desc');
  const [orderBy, setOrderBy] = React.useState<keyof IStock>('marketCap');
  const [selected, setSelected] = React.useState<readonly string[]>([]);
  const [page, setPage] = React.useState(0);
  const [rowsPerPage, setRowsPerPage] = React.useState(50);
  
  useEffect(() => {
}, [rows]);

  const handleClick = (code: string) => {
    debugger;
    window.location.href = '#/stocks/'+code;
  };

  const handleChangePage = (event: unknown, newPage: number) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  // Avoid a layout jump when reaching the last page with empty rows.
  const emptyRows =
    page > 0 ? Math.max(0, (1 + page) * rowsPerPage - rows.length) : 0;

  const visibleRows = React.useMemo(
    () =>
      [...rows]
        .sort(getComparator(order, orderBy))
        .slice(page * rowsPerPage, page * rowsPerPage + rowsPerPage),
    [order, orderBy, page, rowsPerPage, rows]
  );

    const handleSelectAllClick = (event: React.ChangeEvent<HTMLInputElement>) => {
      if (event.target.checked) {
        const newSelected = rows.map((n) => n.code);
        setSelected(newSelected);
        return;
      }
      setSelected([]);
    };

  const handleRequestSort = (
    event: React.MouseEvent<unknown>,
    property: keyof IStock
  ) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  return (
    <div>
        <Table
          sx={{ minWidth: 750 }}
          aria-labelledby="tableTitle"
          size={'medium'}
        >
          
          <EnhancedTableHead
            numSelected={selected.length}
            order={order}
            orderBy={orderBy}
            onSelectAllClick={handleSelectAllClick}
            onRequestSort={handleRequestSort}
            rowCount={rows.length}
          />
          <table></table>
          <TableBody>
            {visibleRows.map((row, index) => {
              return (
                <TableRow
                onClick={(event) => handleClick(row.code)}
                  hover
                  
                  // role="checkbox"
                  // aria-checked={isItemSelected}
                  // tabIndex={-1}
                  key={row.stockKey}
                >
                  <TableCell sx={{ cursor: 'pointer' }}  onClick={(event) => handleClick(row.code)} align="left">
                  
                  <div className="d-flex px-2 py-1">
                          {StockAvatar(row.code)}
                          <div className="d-flex flex-column justify-content-center">
                            <h6 className="text-xs text-secondary mb-0 font-weight-bold">{row.code}</h6>
                            <p className="text-xs text-secondary mb-0">{row.name}</p>
                          </div>
                        </div>

                  </TableCell>
 
                    <TableCell sx={{ cursor: 'pointer' }} onClick={(event) => handleClick(row.name)} align="left">
                      <p className="text-xs text-secondary mb-0">
                        {row.sector}
                      </p>
                    </TableCell>
                    <TableCell sx={{ cursor: 'pointer' }} onClick={(event) => handleClick(row.name)} align="left">
                      <p className="text-xs text-secondary mb-0">
                        {row.marketCap} Cr
                      </p>
                    </TableCell>
                    <TableCell sx={{ cursor: 'pointer' }} onClick={(event) => handleClick(row.name)} align="left">
                    <p className="text-xs text-secondary mb-0">
                        {row.isinNumber}
                      </p>
                    </TableCell>
                    <TableCell sx={{ cursor: 'pointer' }} onClick={(event) => handleClick(row.name)} align="left">
                      <p className="text-xs text-secondary mb-0">
                      {row.isBSEListed && <a className="btn-link text-success text-gradient" target="blank" href={row.bseURL}>BSE <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a>}
                      {row.isNSEListed && <a className="btn-link text-success text-gradient" target="blank" href={'https://www.nseindia.com/get-quotes/equity?symbol='+row.code}>NSE <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a>}
                      </p>
                    </TableCell>
                </TableRow>
              );
            })}
            {emptyRows > 0 && (
              <TableRow>
                <TableCell colSpan={6} />
              </TableRow>
            )}
          </TableBody>
        </Table>
      <TablePagination
        hidden={rows.length<rowsPerPage}
        rowsPerPageOptions={[5, 10, 25,50,100]}
        component="div"
        count={rows.length}
        rowsPerPage={rowsPerPage}
        page={page}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
      />
    </div>
  );
}

function descendingComparator<T>(a: T, b: T, orderBy: keyof T) {
  if (b[orderBy] < a[orderBy]) {
    return -1;
  }
  if (b[orderBy] > a[orderBy]) {
    return 1;
  }
  return 0;
}

type Order = 'asc' | 'desc';

function getComparator<Key extends keyof any>(
  order: Order,
  orderBy: Key
): (
  a: { [key in Key]: number | string | Date | Boolean},
  b: { [key in Key]: number | string | Date | Boolean}
) => number {
  return order === 'desc'
    ? (a, b) => descendingComparator(a, b, orderBy)
    : (a, b) => -descendingComparator(a, b, orderBy);
}

interface HeadCell {
  disablePadding: boolean;
  id: keyof IStock;
  label: string;
  numeric: boolean;
  disableSort?: boolean;
}

const headCells: readonly HeadCell[] = [
  {
    id: 'code',
    numeric: false,
    disablePadding: true,
    label: 'Stock',
  },
  {
    id: 'sector',
    numeric: false,
    disablePadding: true,
    label: 'Sector',
  },
  {
    id: 'marketCap',
    numeric: false,
    disablePadding: true,
    label: 'Market Cap(Cr.)',
  },
  {
    id: 'isinNumber',
    numeric: false,
    disablePadding: true,
    label: 'ISIN Number',
  },
];

interface EnhancedTableProps {
  numSelected: number;
  onRequestSort: (
    event: React.MouseEvent<unknown>,
    property: keyof IStock
  ) => void;
  onSelectAllClick: (event: React.ChangeEvent<HTMLInputElement>) => void;
  order: Order;
  orderBy: string;
  rowCount: number;
}

function EnhancedTableHead(props: EnhancedTableProps) {
  const {
    order,
    orderBy,
    onRequestSort,
  } = props;
  const createSortHandler =
    (property: keyof IStock) => (event: React.MouseEvent<unknown>) => {
      onRequestSort(event, property);
    };

 
    return (
      <TableHead>
        <TableRow>
          {headCells.map((headCell) =>
          (
            <TableCell
              key={headCell.id}
              align={'left'}
              padding={headCell.disablePadding ? 'none' : 'normal'}
              sortDirection={orderBy === headCell.id ? order : false}
            >
            <TableSortLabel
                active={orderBy === headCell.id}
                direction={orderBy === headCell.id ? order : 'asc'}
                onClick={createSortHandler(headCell.id)}
              >
                <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>
                  {headCell.label}
                </div>
                {orderBy === headCell.id ? (
                  <Box component="span" sx={visuallyHidden}>
                    {order === 'desc' ? 'sorted descending' : 'sorted ascending'}
                  </Box>
                ) : null
                }
              </TableSortLabel>

            </TableCell>
          ))}
            <TableCell>
                <div className='text-uppercase text-secondary text-xxs font-weight-bolder opacity-7'>
                 Exchanges
                </div>
            </TableCell>
        </TableRow>
      </TableHead>
    );

}

interface IStockTableTableTableProps{
    rows:IStock[]
}

export default StocksTable;
