import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { useParams } from 'react-router-dom';
import IAnnouncement from '../../models/announcement/announcement';
import { getColor } from '../../utility/utility';
import dayjs from 'dayjs';
import AnnouncementsComp from './announcementComp';

const Announcement = () => {
  const params= useParams();
  const [announcement, setAnnoncement] = useState<IAnnouncement|undefined>(
    undefined);

    const loadAnnouncement = async (announcementKey:string) => {
              await axios({
                  url: backend+'announcements/'+announcementKey,
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IAnnouncement = res.data;
                      debugger;
                      setAnnoncement(data);
                  })
                  .catch((err) => {
                    //window.alert('unable to get alert details')
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(params && params["announcementKey"]){
        loadAnnouncement(params["announcementKey"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const headerName = announcement?.stockCode+"'s Other Announcements";

    return (
      <div className="container">
       { announcement && <div className="card">
            <div className="card-header"> 
            <div className="row">
                <div className="d-flex align-items-center mt-1">
                                        <div style={{color:getColor(announcement.stockCode)}}
                                         className="avatar avatar-sm me-3 border-radius-lg">
                                            {announcement.stockCode.substring(0,5)}</div>
                    <h6 className="mb-0">{announcement.stockName}</h6>
                    <p className="ml-5 mb-0 font-weight-normal text-sm">
              /  {announcement.category} <small><i>on {dayjs(announcement.announcementDate).format("MMM D, YYYY h:mm A")}</i></small>
              </p>
                    </div></div>
            </div>
                <div className="card-body p-3">
                  <ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Company:</strong> &nbsp; {announcement.stockName} (#{announcement.stockCode})</li>
                    <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Category:</strong> &nbsp; {announcement.category}</li>
                    <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Summary:</strong> &nbsp; {announcement.aiSummary ?? announcement.subject}</li>
                 
                    <li className="list-group-item border-0 ps-0 text-sm"><strong className="text-dark">Announcement Date:</strong> &nbsp; {dayjs(announcement.announcementDate).format("MMM D, YYYY h:mm A")}</li>
                    <li className="list-group-item border-0 ps-0 text-sm"><strong className="text-dark">Exchange:</strong> &nbsp; {announcement.source}</li>
                    <li className="list-group-item border-0 ps-0 text-sm">
                      <strong className="text-dark">Announcement PDF:</strong> &nbsp; <a className="btn-link text-success text-gradient" target='blank' href={announcement.url}>
                      Announcement URL <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a></li>
                    <li className="list-group-item border-0 ps-0 text-sm"><strong className="text-dark">Impression:</strong> &nbsp; {announcement.impression}</li>
                  </ul>
                  <AnnouncementsComp headerName={headerName} filterbyStock={announcement.stockCode}></AnnouncementsComp>
            </div>
      </div>
      }
</div>

)}

export default Announcement;
