import React, {useEffect, useState} from 'react';
import axios from 'axios';
import { backend } from '../../models/contants/contants';
import { useParams } from 'react-router-dom';
import { getColor } from '../../utility/utility';
import AnnouncementsComp from '../announcement/announcementComp';
import { IStock } from '../../models/stock/stock';
import { StockAvatar } from '../common/utilitycomp';

const Stock = () => {
  const params= useParams();
  const [stock, setStock] = useState<IStock|undefined>(
    undefined);

    const loadStock = async (stockCode:string) => {
              await axios({
                  url: backend+'stocks/'+stockCode,
                  method: "Get",
                  headers: {
                      authorization: "your token comes here",
                  }
              })
                  .then((res) => {
                      const data: IStock = res.data;
                      debugger;
                      setStock(data);
                  })
                  .catch((err) => {
                    //window.alert('unable to get alert details')
                  });
          }
 // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
      if(params && params["stockCode"]){
        loadStock(params["stockCode"]);
      }
       // eslint-disable-next-line react-hooks/exhaustive-deps
    },[]);

    const headerName = stock?.code+"'s Announcements";

    return (
      <div className="container">
       { stock && <div className="card">
            <div className="card-header"> 
            <div className="row">
                <div className="d-flex align-items-center mt-1">
                                        {StockAvatar(stock.code)}
                    <h6 className="mb-0">{stock.name}</h6>
                    <p className="ml-5 mb-0 font-weight-normal text-sm">
              </p>
                    </div></div>
            </div>
                <div className="card-body p-3">
                  <ul className="list-group mb-3">
                  <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Company:</strong> &nbsp; {stock.name} (#{stock.code})</li>
                    <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Sector:</strong> &nbsp; {stock.sector}</li>
                    <li className="list-group-item border-0 ps-0 text-sm">
                    <strong className="text-dark">Market Cap:</strong> &nbsp; {stock.marketCap } Cr</li>
                 
                    <li className="list-group-item border-0 ps-0 text-sm">
                      <strong className="text-dark">Exchanges Listed In:</strong> &nbsp; 
                     {stock.isBSEListed } <a className="btn-link text-success text-gradient" target='blank' href={stock.bseURL}>
                      BSE <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a>
                      {stock.isNSEListed } <a className="btn-link text-success text-gradient" target='blank' href={stock.bseURL}>
                       NSE <i className="material-symbols-rounded text-sm me-2">open_in_new</i></a>
                      </li>
                  </ul>
                  <AnnouncementsComp headerName={headerName} filterbyStock={stock.code}></AnnouncementsComp>
            </div>
      </div>
      }
</div>

)}

export default Stock;
